'use strict'

import { ITEM_FIVE_RUPESS, CHARACTER_MERCHANT, SPRITE_TEXT_COLOR_WHITE, SPRITE_TEXT_HEIGHT, TILE_WIDTH, TILE_HEIGHT, SPRITE_TEXT_WIDTH } from '../constant'
import textManager from '../service/text-manager'
import resource from '../resource'

class Character {
  constructor (name, column, line, x, y, width, height, sprite, text) {
    this.name = name
    this.column = column
    this.line = line
    this.x = x
    this.y = y
    this.width = width
    this.height = height
    this.sprite = sprite
    this.text = text
    this.displayedText = ''
    this.enabled = true
  }

  init () {
    this.sprite.start()
    this.enabled = true
  }

  reset () {
    this.sprite.stop()
    this.displayedText = ''
  }

  hasStoppedTalking () {
    return this.displayedText === this.text
  }

  draw (context) {
    this.vanishDrawingCalled = true
    if (!this.enabled) {
      return
    }
    
    this.sprite.draw(context, this.x, this.y, this.width, this.height)
    //if (this.name === CHARACTER_MERCHANT) {
    //resource.getItemSprite(ITEM_FIVE_RUPESS).draw(context, TILE_WIDTH * 2, 7 * TILE_HEIGHT, TILE_WIDTH, TILE_HEIGHT)
    //textManager.draw(context, 'x', SPRITE_TEXT_COLOR_WHITE, TILE_WIDTH * 3, 7 * TILE_HEIGHT, TILE_WIDTH, TILE_HEIGHT)
    //}
    textManager.draw(context, this.text, SPRITE_TEXT_COLOR_WHITE, this.x - 4.5 * TILE_WIDTH - TILE_WIDTH / 2, this.y - SPRITE_TEXT_HEIGHT * 3, 11 * TILE_WIDTH, SPRITE_TEXT_HEIGHT * 3, 'middle', this.displayedText.length)
  }

  vanish (timeout) {
    const self = this
    self.displayedText = ''
    const interval = setInterval(() => {
      if (self.vanishDrawingCalled) {
        self.enabled = !self.enabled
        self.vanishDrawingCalled = false
      }
    }, 5)
    setTimeout(() => {
      clearInterval(interval)
      self.enabled = false
    }, timeout)
  }
}

export { Character }
