'use strict'

import Game from './game'
import { Debug } from './debug'
import io from '../utils/io'
import resource from '../resource'
import soundManager from '../service/sound-manager'
import worldManager from '../service/world-manager'
import { PATH_DATA_GAME, FILE_TYPE_LOZ, GAME_INTERVAL_PROCESS, GAME_INTERVAL_DRAWING, GAME_INTERVAL_INPUT, TILES_PER_LINE, TILES_PER_COLUMN, TILE_WIDTH, TILE_HEIGHT, GAME_TOP_MENU_HEIGHT } from '../constant'

let game
let drawInterval
let processInterval
let processInputInterval
const canvas = document.querySelector('#loz-canvas')
const context = canvas.getContext('2d')

canvas.width = TILES_PER_LINE * TILE_WIDTH
canvas.height = TILES_PER_COLUMN * TILE_HEIGHT + GAME_TOP_MENU_HEIGHT
canvas.onload = () => { canvas.focus() }

const debug = new Debug(
  document.querySelector('input#control-blocking-zones'),
  document.querySelector('input#control-blocking-zones-color'),
  document.querySelector('input#control-rupees'),
  document.querySelector('input#control-rupees-submit'),
  document.querySelector('input#control-keys'),
  document.querySelector('input#control-keys-submit'),
  document.querySelector('input#control-bombs'),
  document.querySelector('input#control-bombs-submit'),
  document.querySelector('input#control-convert-file-to-loz')
)
soundManager.initContext()
soundManager.initEvents(document.querySelector('input#play-sounds'), document.querySelector('input#control-volume'))
await resource.loadAll()

async function loadGame (gameData) {
  worldManager.createMaps(gameData)

  game = new Game()
  debug.setGame(game)

  clearInterval(drawInterval)
  drawInterval = setInterval(() => {
    game.draw(context, 0, 0, canvas.width, canvas.height)
    debug.draw(context, 0, 0, canvas.width, canvas.height)
  }, GAME_INTERVAL_DRAWING)
  clearInterval(processInterval)
  processInterval = setInterval(() => game.process(), GAME_INTERVAL_PROCESS)
  clearInterval(processInputInterval)
  processInputInterval = setInterval(() => game.processInput(), GAME_INTERVAL_INPUT)

  game.start()
}

const gameData = await io.fetchRemoteFile(PATH_DATA_GAME)
await loadGame(gameData)

document.querySelector('input#control-import-game').addEventListener('click', async (e) => {
  e.preventDefault()
  const gameData = await io.openFile(FILE_TYPE_LOZ)
  loadGame(gameData)
})
